<?php
require_once __DIR__.'/bootstrap.php';$user=current_user($pdo);$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);if(!$id){http_response_code(404);exit('Post not found');}
$q=$pdo->prepare(feed_query().' WHERE p.id=:id');$q->execute(['viewer'=>me()??0,'id'=>$id]);$post=$q->fetch();if(!$post){http_response_code(404);exit('Post not found');}
$q=$pdo->prepare(feed_query().' WHERE p.parent_id=:id ORDER BY p.created_at ASC,p.id ASC LIMIT 100');$q->execute(['viewer'=>me()??0,'id'=>$id]);$replies=$q->fetchAll();page_top('Thread',$user);?><div class="heading"><a href="index.php">←</a><strong>Thread</strong></div><?php render_post($post);?>
<?php if($user):?><form class="compose reply" method="post" action="action.php"><div class="avatar"><?=e(mb_strtoupper(mb_substr($user['display_name'],0,1)))?></div><div class="compose-content"><strong><?=e($user['username'])?></strong><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="post"><input type="hidden" name="parent_id" value="<?= $id ?>"><textarea name="body" maxlength="500" required rows="2" placeholder="Reply to <?=e($post['username'])?>..."></textarea><div class="compose-footer"><small class="counter">0 / 500</small><button class="pill">Reply</button></div></div></form><?php else:?><p class="reply-login"><a href="auth.php">Log in</a> to reply.</p><?php endif;?><div class="section-label">Replies</div><?php foreach($replies as $reply) render_post($reply); if(!$replies) echo '<div class="empty">No replies yet.</div>';page_bottom();?>
